mapper.select:
SELECT FINPROD_ID id, FINPROD_NAME text, FINPROD_ID object FROM FIN_PRODUCT
FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND (FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR FINPROD_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND FINPROD_MARKET_ID = #{initValue}

select count(1)
from FIN_EXERCISE_PLAN
where
FINPROD_ID = #{seccode}
and EXERCISE_DATE > = #{sysDate,jdbcType=DATE}
